#!/usr/bin/env python3
"""Verify final RAM6 image/check ties and write reviewable bundle metadata."""
from pathlib import Path
import hashlib,json,zlib
r=Path(__file__).resolve().parent;e=r/'evidence';assert not (r/'c80-openwrt-ram6-fwdl.zip').exists()
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
log=(r/'verification-core.log').read_text();assert 'PASS:80' in log
assert len([x for x in log.splitlines() if x.startswith('PASS ')])==80
assert json.loads((e/'stock-download-traces.json').read_text())['cases_passed']==23
assert json.loads((e/'stock-main-traces.json').read_text())['cases_passed']==27
assert len(json.loads((e/'rootfs-elf-closure.json').read_text()))==57
fw=json.loads((r/'FIRMWARE-SOURCES.json').read_text());assert len(fw['files'])==6
qemu={}
for mode in ('missing-firmware','aon-refusal'):
 q=json.loads((e/f'qemu-{mode}-result.json').read_text());assert q['passed']
 assert sha(r/'build/usr/initramfs_data.cpio')==q['rootfs_cpio_sha256']
 assert sha(r/'build-qemu/arch/arm/boot/zImage')==q['qemu_kernel_sha256']
 qemu[mode]=len(q['commands'])
 if mode=='aon-refusal':assert q['normal_reboot_and_C80_callback_before_PSCI_fallback']
assert 'All twenty files match' in (r/'artifacts/patch-verification.txt').read_text()
assert json.loads((e/'ram5-change-scope.json').read_text())['passed']
assert json.loads((e/'stock-dma-mode-traces.json').read_text())['cases_passed']==15
restart=json.loads((e/'restart-result.json').read_text());assert restart['passed'] and restart['cases_passed']==8
assert restart['Linux_vmlinux_sha256']==sha(r/'build/vmlinux')
decompressor=json.loads((e/'decompressor-result.json').read_text());assert decompressor['passed']
assert decompressor['zimage_sha256']==sha(r/'c80-openwrt-ram6-fwdl-zImage') and len(decompressor['checks'])==6
handoff=json.loads((e/'handoff-verification.json').read_text());assert len(handoff['cases'])==5 and all(x['status']=='pass' for x in handoff['cases'])
assert handoff['payload_sha256']==sha(r/'c80-openwrt-ram6-handoff.bin')
records=[]
for address,name in ((0x41000000,'c80-openwrt-ram6-fwdl-zImage'),(0x40f00000,'c80-openwrt-ram6-fwdl.dtb'),(0x40e00000,'c80-openwrt-ram6-handoff.bin')):
 data=(r/name).read_bytes();records.append({'file':name,'address':hex(address),'bytes':len(data),'crc32':f'{zlib.crc32(data):08x}','sha256':sha(r/name)})
assert (r/'c80-openwrt-ram6-fwdl-zImage').read_bytes()==(r/'build/arch/arm/boot/zImage').read_bytes()
assert (r/'c80-openwrt-ram6-fwdl.dtb').read_bytes()==(r.parent/'openwrt-ram4-patch/c80-openwrt-ram4-patch.dtb').read_bytes()
assert (r/'c80-openwrt-ram6-handoff.bin').read_bytes()==(r.parent/'openwrt-ram4-patch/c80-openwrt-ram4-handoff.bin').read_bytes()
assert (r/'c80-script-runner.bin').stat().st_size==4732
lines=[x for x in (r/'c80-start.txt').read_text().splitlines() if not x.startswith('#')];assert len(lines)==6 and lines[0]=='C80SCRIPT1' and lines[-2]=='go 40e00000'
for row in records:assert f"load {int(row['address'],16):08x} {row['file']} {row['bytes']:08x} {row['crc32']}" in lines
p={'kernel':'6.12.113-c80-openwrt-ram6-fwdl','userspace':'OpenWrt25.12.5 r33051-f5dae5ece4; unchanged35packages/57ELF','load_files':records,'script_bytes':(r/'c80-start.txt').stat().st_size,'hardware_tested':False,'physical_main_download_start_state3_tested':False,'parent_RAM4_patch_download_readiness_and_cleanup_passed':True,'parent_software_reboot_after_MCU_confirmed':True,'parent_RAM5_main_result':{'primary':19,'payload_completed_bytes':1920,'start_attempted':0,'cleanup':0,'critical':0},'download_mode':{'register':'0x18004208','mask':'0x200','OEM_callback':'0x40308dd0','command_ring_retained':15,'scatter_ring_retained':3,'hardware_effect_unproven':True},'scope':'OEM download-mode bit9 plus exact supplied WIFI_RAM_CODE_7626.bin after patch, 3 regions/25616 payload bytes/29fragments, start flags0/address0 then sync state3; no AP/RF/IRQ-enable/NOR commands','main_firmware':{'file':'WIFI_RAM_CODE_7626.bin','bytes':25808,'CRC32':'92c09901','SHA256':'76a9a4fb62be68725fba016d0814911255cf62b819d41760198dc7e3911322b5','regions':[{'MCU_address':'0x20400','bytes':2896,'chunks':4},{'MCU_address':'0x2010000','bytes':1584,'chunks':2},{'MCU_address':'0x40100000','bytes':21136,'chunks':23}],'initial_sync_state':1,'post_start_sync_state':3,'sync_CPU_address':'0x180c1140','sync_mask':'0xe'},'checks':{'actual_OEM_ARM_patch_contract':23,'actual_OEM_ARM_main_contract':27,'actual_OEM_ARM_download_mode':15,'actual_C_core_ASan_UBSan':80,'QEMU_command_checks':qemu,'actual_ARM_decompressor':6,'actual_ARM_handoff':5,'actual_ARM_restart':8,'ELF_ABI_closure':57,'Linux_patch_files_apply_exact':20,'new_build_compiled_and_verified':True},'source_scope':'evidence/ram5-change-scope.json','rootfs_firmware_scope':'Six exact generic user-supplied OEM blobs; FIRMWARE-SOURCES.json; no individual calibration','not_proven':['physical main transfer/start/generic ACK/state3','Wi-Fi IRQ','RF/calibration/AP/association','cold power equivalence','flash installation'],'cleanup':'Same owned controls, GLO, mask and writable4rings; pin coherent pool if MCU/DMA stop fails','fresh_boot_required_after_attempt':True,'new_power_off_requested_for_next_test':False,'issued_parent_artifacts_immutable':True}
(r/'PROVENANCE.json').write_text(json.dumps(p,indent=2)+'\n')
(e/'script-result.json').write_text(json.dumps({'passed':True,'records':records,'script_bytes':p['script_bytes'],'unchanged_hardware_confirmed_runner':True},indent=2)+'\n')
readme='# OpenWrt RAM6: режим загрузки Wi-Fi DMA\n\nRAM5 повторно загрузила patch, но передача основного кода остановилась на\nтретьем фрагменте после1920B. MCU/DMA остановлены, cleanup0/critical0.\nЗаводской MT7626 перед загрузкой включает bit9 в GLO18004208; наша RAM5\nпропускала этот режим. RAM6 исправляет это конкретное расхождение. Причину\nостановки на аппаратуре ещё предстоит подтвердить; полного main ready пока нет.\n\nРежим проверяется до каждого пакета. При таймауте до cleanup сохраняются\ndescriptor и CPU/DMA индексы очереди. Сохраняются проверенные TX15 команды\nи FWDL3 scatter; подробности отличия от OEM — evidence/dma-mode-contract.md.\nНастройка AP/RF пока не добавляется, NOR только читается.\n\n## Пять файлов в TFTP\n\nСкопируйте из этого архива в корень TFTP c80-script-runner.bin, новый\nc80-start.txt (заменить прежний) и три файла из таблицы. ПК остаётся\nв LAN1 с192.168.0.3/24. Старые файлы можно сохранить отдельно.\n\n|Файл|Байт|CRC32|\n|---|---:|---|\n'+''.join(f"|{x['file']}|{x['bytes']}|{x['crc32']}|\n" for x in records)+'\n## Загрузка из текущего OpenWrt\n\nВ текущей оболочке выполните `reboot`, затем остановите Autoboot до\n`MT7626>`. Дополнительное выключение питания сейчас не требуется.\nВ U-Boot отдельно:\n\n```text\nsetenv autostart no\ntftpboot 40280000 c80-script-runner.bin\n```\n\nПосле успешной передачи4732байт:\n\n```text\ngo 40280000\n```\n\nПомощник проверит размеры/CRC и загрузит ядро6.12.113-c80-openwrt-ram6-fwdl.\nПосле Enter/root shell вводите короткие команды по одной, с ожиданием prompt.\nНе вставляйте весь блок сразу: polling UART терял окончания длинных строк.\n\n```sh\nuname -r\ncd /sys/kernel\ncd c80_wifi\ncat status\n```\n\nЕсли ran=0/finished=0, отдельно:\n\n```sh\necho 1 > run\n```\n\nДождитесь prompt, затем отдельно:\n\n```sh\ncat status\nfree\n```\n\nПришлите весь вывод uname→free, включая стадии ядра. После опыта оставайтесь\nв OpenWrt. Повторный run в одной загрузке не нужен; guards не обходить.\n\n## Что проверяем\n\nУспех: result/primary/cleanup/critical0; patch1808B/2chunks/ready1; main\nregions3/3, bytes25616/chunks29, address_valid7/status0/0/0, region bytes\n2896/1584/21136, chunks4/2/23; start_valid1/status0, main_ready1 и sync\nbits3:1=3 (masked raw6). При свежем patch ожидаются TX40/40=command9/9+\nFWDL31/31, RX9, sequence10. При уже готовом patch — TX34/RX5, FWDL29.\n\ndownload_mode_checked1, enable_glo и last_glo содержат bit200. На прежнем\nсвежем GLO ожидается10001e75 во время передачи; busy-биты могут меняться.\nПосле остановки точный GLO10001870 и IRQmask0 восстановлены, DMAidle1/\nMCUstopped1/pools_retained0. Cleanupflags/owned_bad/rings_bad0. Чужие\ncontrol bitsb0e20 сохраняются и показываются отдельно, как на RAM3–5.\nReadonly DMA indices не считаются обычными writable полями.\n\nЕсли повторится таймаут, failure_snapshot1 содержит фазу, ring/slot,\nCPU/DMA indices, descriptor4words и GLO/mask/source/sync/own ДО cleanup.\nЭто чтение, без diagnostic-selector/ack/reset записей. Код23 означает\nотказ readback режима или его потерю: новые пакеты не отправляются.\nКод19 — FWDL timeout;18 — MCU rejection;21/22 — initial/final sync failure.\nПолные счётчики и first failure сохраняются; таймаут не выдаётся за успех.\n\nПосле любого опыта нужен fresh boot. Critical80/81 закрепляет coherent\npool при неподтверждённой остановке. Обычный reboot аппаратно проверен\nпосле MCU родительскими сборками; равенство полному снятию питания не доказано.\n\n## Локальная проверка и границы\n\n80 actual-C ASan/UBSan сценариев с39 OEM packet oracle,15 новых сценариев\nнастоящего OEM ARM download-mode,27 main/23 patch ARM контрактов. Новая\nсборка прошла33+31 QEMU проверки userspace/sysfs/refusal/reboot,6 ARM\ndecompressor/5handoff/8restart,57ELF и20-fileLinuxpatch. Проверен полный\nsource scope: изменились только два MCU файла; rootfs побайтно как RAM5.\nQEMU не эмулирует C80, MCU или RF; ответы DMA/MMIO в моделях синтетические.\n\nВсе шесть generic OEM файлов прежние, длины/CRC проверяются до MMIO.\n2MiB EMI no-map, bounded waits, once-per-boot, IRQmask0, stop/restore\nзащиты сохранены. Runtime diff — ram5-to-ram6.patch. Выданная RAM5 и\nкаждый записанный член её архива проверены неизменными.\n\nWi-Fi main transfer/start/state3, AP/ассоциация/калибровки/RF, Wi-Fi IRQ,\nсамостоятельный cold init и установка во flash ещё не подтверждены.\nRoot/settings временные вRAM; после reboot образ нужно загрузить заново.\nИндивидуальные калибровки/MAC/пароли, TPOS, полный U-Boot/NOR не включены.\nOEM лицензии сохранены; общие права распространения не заявляются.\n'
(r/'README.md').write_text(readme)
print(json.dumps({'load_files':records,'checks':p['checks'],'script_bytes':p['script_bytes']},indent=2))
